import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { createClient } from '@/lib/supabase/server'
import { TodayClient } from '@/components/today/TodayClient'
import { ArtistTodayDashboard } from '@/components/today/ArtistTodayDashboard'
import type { GettingStartedCounts } from '@/components/dashboard/GettingStartedCard'
import { getArtistIdForUser, getArtistEarningsToday } from '@/lib/today/queries'
import { getTodayHeroData, getMostUrgentOverdueItem } from '@/lib/dashboard/today-hero'
import { getNextUpItems } from '@/lib/dashboard/next-up'
import { getTodayScheduleData } from '@/lib/dashboard/today-schedule'
import { getWeekRevenueData } from '@/lib/dashboard/week-revenue'
import { getArtistUtilizationData } from '@/lib/dashboard/artist-utilization'
import { getPendingDepositsData } from '@/lib/dashboard/pending-deposits'
import { getConsentStatusData } from '@/lib/dashboard/consent-status'
import { getLowInventoryData } from '@/lib/dashboard/low-inventory'
import { getGuestResidencyData } from '@/lib/dashboard/guest-residency'
import type { Database } from '@/lib/supabase/types'

export const metadata: Metadata = {
  title: 'Today — InkOS',
}

type StudioRole = Database['public']['Tables']['studio_members']['Row']['role']

export default async function TodayPage() {
  const supabase = await createClient()
  const {
    data: { user },
  } = await supabase.auth.getUser()

  if (!user) redirect('/login')

  const [profileResult, memberResult] = await Promise.all([
    supabase
      .from('profiles')
      .select('full_name')
      .eq('id', user.id)
      .single(),
    supabase
      .from('studio_members')
      .select('studio_id, role, studios(name, timezone)')
      .eq('user_id', user.id)
      .is('deactivated_at', null)
      .order('created_at', { ascending: true })
      .limit(1)
      .single(),
  ])

  const firstName = profileResult.data?.full_name?.split(' ')[0] ?? 'there'
  const studioData = memberResult.data?.studios as { name: string; timezone: string } | null
  const studioName = studioData?.name ?? 'My Studio'
  const timezone = studioData?.timezone ?? 'UTC'
  const hasStudio = !!memberResult.data?.studio_id
  const studioId = memberResult.data?.studio_id
  const role: StudioRole = memberResult.data?.role ?? 'owner'

  let gettingStartedCounts: GettingStartedCounts = {
    services: 0,
    artists: 0,
    schedules: 0,
    bookings: 0,
    bookingPageConfigured: false,
  }

  let ownArtistId: string | null = null
  let artistEarningsToday = 0

  if (studioId) {
    const [servicesRes, artistsRes, schedulesRes, bookingsRes, bpRes] = await Promise.all([
      supabase
        .from('services')
        .select('id', { count: 'exact', head: true })
        .eq('studio_id', studioId),
      supabase
        .from('artists')
        .select('id', { count: 'exact', head: true })
        .eq('studio_id', studioId),
      supabase
        .from('artist_schedules')
        .select('id', { count: 'exact', head: true })
        .eq('studio_id', studioId),
      supabase
        .from('bookings')
        .select('id', { count: 'exact', head: true })
        .eq('studio_id', studioId),
      supabase
        .from('booking_page_settings')
        .select('studio_id', { count: 'exact', head: true })
        .eq('studio_id', studioId),
    ])

    gettingStartedCounts = {
      services: servicesRes.count ?? 0,
      artists: artistsRes.count ?? 0,
      schedules: schedulesRes.count ?? 0,
      bookings: bookingsRes.count ?? 0,
      bookingPageConfigured: (bpRes.count ?? 0) > 0,
    }

    if (role === 'artist' || role === 'guest_artist') {
      ownArtistId = await getArtistIdForUser(supabase, studioId, user.id)
      if (ownArtistId) {
        artistEarningsToday = await getArtistEarningsToday(supabase, studioId, ownArtistId)
      }
    }
  }

  // S19: artist and guest_artist roles see their personal dashboard
  if ((role === 'artist' || role === 'guest_artist') && studioId && ownArtistId) {
    return (
      <ArtistTodayDashboard
        firstName={firstName}
        studioId={studioId}
        artistId={ownArtistId}
        artistEarningsToday={artistEarningsToday}
      />
    )
  }

  // ── Dashboard widget data (owner/admin only) ──────────────────────────────────
  const [
    heroData,
    urgentOverdueItem,
    nextUpItems,
    scheduleData,
    weekRevenueData,
    artistUtilizationData,
    pendingDepositsData,
    consentStatusData,
    lowInventoryData,
    guestResidencyData,
  ] = studioId
    ? await Promise.all([
        getTodayHeroData(supabase, studioId, timezone),
        getMostUrgentOverdueItem(supabase, studioId, timezone),
        getNextUpItems(supabase, studioId),
        getTodayScheduleData(supabase, studioId),
        getWeekRevenueData(supabase, studioId),
        getArtistUtilizationData(supabase, studioId),
        getPendingDepositsData(supabase, studioId),
        getConsentStatusData(supabase, studioId),
        getLowInventoryData(supabase, studioId),
        getGuestResidencyData(supabase, studioId),
      ])
    : [null, null, [], null, null, null, null, null, null, null] as const

  return (
    <TodayClient
      firstName={firstName}
      studioName={studioName}
      timezone={timezone}
      hasStudio={hasStudio}
      studioId={studioId ?? null}
      role={role}
      ownArtistId={ownArtistId}
      artistEarningsToday={artistEarningsToday}
      gettingStartedCounts={gettingStartedCounts}
      heroData={heroData}
      urgentOverdueItem={urgentOverdueItem}
      nextUpItems={nextUpItems}
      scheduleData={scheduleData}
      weekRevenueData={weekRevenueData}
      artistUtilizationData={artistUtilizationData}
      pendingDepositsData={pendingDepositsData}
      consentStatusData={consentStatusData}
      lowInventoryData={lowInventoryData}
      guestResidencyData={guestResidencyData}
    />
  )
}

'use client'

import { useState } from 'react'
import Link from 'next/link'
import { toast } from 'sonner'
import {
  CreditCard,
  Heart,
  ShoppingBag,
} from 'lucide-react'
import type { LucideIcon } from 'lucide-react'
import { cn } from '@/lib/utils'

interface QuickAction {
  id: string
  label: string
  description: string
  icon: LucideIcon
  accentClass: string
  iconBgClass: string
}

const ACTIONS: QuickAction[] = [
  {
    id: 'deposit',
    label: 'Take Deposit',
    description: 'Collect a deposit for an upcoming booking',
    icon: CreditCard,
    accentClass: 'hover:border-[var(--color-status-confirmed)]/40',
    iconBgClass: 'bg-[var(--color-primary)]/10 text-[var(--color-primary)]',
  },
  // Walk-in Booking removed — redundant with New Appointment in top bar
  // TODO: Invite Artist belongs on /team page — add shortcut there
  {
    id: 'aftercare',
    label: 'Send Aftercare',
    description: 'Send aftercare instructions to a client',
    icon: Heart,
    accentClass: 'hover:border-[var(--color-consent-signed)]/40',
    iconBgClass: 'bg-[var(--color-success-bg)] text-[var(--color-success-foreground)]',
  },
  {
    id: 'sale',
    label: 'Record Sale',
    description: 'Log a retail product or service sale',
    icon: ShoppingBag,
    accentClass: 'hover:border-[var(--color-warning)]/40',
    iconBgClass: 'bg-[var(--color-warning-bg)] text-[var(--color-warning-foreground)]',
  },
]

export function TodayQuickActionsRow() {
  function handleAction(id: string) {
    if (id === 'aftercare') {
      toast.info('Send Aftercare coming soon')
      return
    }
    if (id === 'sale') {
      toast.info('Record Sale coming soon')
      return
    }
  }

  return (
    <div
      className="grid grid-cols-1 gap-3 sm:grid-cols-3"
      role="toolbar"
      aria-label="Today quick actions"
    >
      {ACTIONS.map((action) => {
        const Icon = action.icon
        if (action.id === 'deposit') {
          return (
            <Link
              key={action.id}
              href="/payments"
              className={cn(
                'group flex flex-col gap-2 rounded-xl border border-[var(--color-border)] bg-[var(--color-card)] p-3.5 transition-all duration-150',
                'hover:shadow-[var(--shadow-card-hover)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--color-ring)] focus-visible:ring-offset-2',
                action.accentClass,
              )}
            >
              <span
                className={cn(
                  'flex h-8 w-8 items-center justify-center rounded-lg transition-transform duration-150 group-hover:scale-105',
                  action.iconBgClass,
                )}
                aria-hidden="true"
              >
                <Icon className="h-4 w-4" />
              </span>
              <span>
                <p className="text-[13px] font-semibold text-[var(--color-foreground)]">
                  {action.label}
                </p>
                <p className="mt-0.5 text-[11px] leading-tight text-[var(--color-muted-foreground)]">
                  {action.description}
                </p>
              </span>
            </Link>
          )
        }

        return (
          <button
            key={action.id}
            type="button"
            className={cn(
              'group flex flex-col gap-2 rounded-xl border border-[var(--color-border)] bg-[var(--color-card)] p-3.5 text-left transition-all duration-150',
              'hover:shadow-[var(--shadow-card-hover)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--color-ring)] focus-visible:ring-offset-2',
              action.accentClass,
            )}
            onClick={() => handleAction(action.id)}
          >
            <span
              className={cn(
                'flex h-8 w-8 items-center justify-center rounded-lg transition-transform duration-150 group-hover:scale-105',
                action.iconBgClass,
              )}
              aria-hidden="true"
            >
              <Icon className="h-4 w-4" />
            </span>
            <span>
              <p className="text-[13px] font-semibold text-[var(--color-foreground)]">
                {action.label}
              </p>
              <p className="mt-0.5 text-[11px] leading-tight text-[var(--color-muted-foreground)]">
                {action.description}
              </p>
            </span>
          </button>
        )
      })}
    </div>
  )
}

'use client'

import Link from 'next/link'
