import type { LucideIcon } from 'lucide-react'
import { Button } from '@/components/ui/button'

// TODO: Invite Artist belongs on /team page — removed from dashboard quick actions

interface QuickAction {
  label: string
  shortcut?: string
  icon: LucideIcon
  href: string
  variant: 'default' | 'outline'
}

const QUICK_ACTIONS: QuickAction[] = [
  { label: 'New Appointment', shortcut: 'N', icon: CalendarPlus, href: '/appointments/new', variant: 'default' },
  { label: 'Add Client', icon: UserPlus, href: '/clients/new', variant: 'outline' },
  { label: 'Send Consent', icon: FilePen, href: '/forms', variant: 'outline' },
]

export function QuickActionsRow() {
  return (
    <div
      className="flex flex-wrap items-center gap-2 motion-safe:animate-in motion-safe:fade-in-0"
      style={{ animationDelay: '100ms', animationFillMode: 'both' }}
