}

'use client'

import { useEffect, useState } from 'react'
import { ActivityFeed } from '@/components/shared/ActivityFeed'
import { AlertsCard } from '@/components/shared/AlertsCard'
import { GettingStartedCard } from '@/components/dashboard/GettingStartedCard'
import { QuickActionsRow } from '@/components/dashboard/QuickActionsRow'
import { EmptyDashboardState } from '@/components/dashboard/EmptyDashboardState'
import { useRecentActivity } from '@/hooks/dashboard/use-recent-activity'
import { useDashboardAlerts } from '@/hooks/dashboard/use-dashboard-alerts'
import type { GettingStartedCounts } from '@/components/dashboard/GettingStartedCard'
import { RoleAwareHero } from './RoleAwareHero'
import { TodayQuickActionsRow } from './QuickActionsRow'
import { ShortcutOverlay } from './ShortcutOverlay'
import { TodayHeroRow } from './TodayHeroRow'
import { OverdueAlertBanner } from './OverdueAlertBanner'
import { NextUpWidget } from './NextUpWidget'
import { TodayScheduleTimelineWidget } from './TodayScheduleTimelineWidget'
import { WeekRevenueTrajectoryWidget } from './WeekRevenueTrajectoryWidget'
import { ArtistUtilizationWidget } from './ArtistUtilizationWidget'
import { PendingDepositsWidget } from './PendingDepositsWidget'
import { ConsentStatusWidget } from './ConsentStatusWidget'
import { LowInventoryWidget } from './LowInventoryWidget'
import { GuestResidencyWidget } from './GuestResidencyWidget'
import type { TodayHeroData, UrgentOverdueItem } from '@/lib/dashboard/today-hero'
import type { NextUpItem } from '@/lib/dashboard/next-up'
import type { TodayScheduleData } from '@/lib/dashboard/today-schedule'
import type { WeekRevenueData } from '@/lib/dashboard/week-revenue'
import type { ArtistUtilizationData } from '@/lib/dashboard/artist-utilization'
import type { PendingDepositsData } from '@/lib/dashboard/pending-deposits'
import type { ConsentStatusData } from '@/lib/dashboard/consent-status'
import type { LowInventoryData } from '@/lib/dashboard/low-inventory'
import type { GuestResidencyData } from '@/lib/dashboard/guest-residency'
import {
  DEMO_HERO_DATA,
  DEMO_NEXT_UP_ITEMS,
  DEMO_SCHEDULE_DATA,
  DEMO_WEEK_REVENUE_DATA,
  DEMO_ARTIST_UTILIZATION_DATA,
  DEMO_PENDING_DEPOSITS_DATA,
  DEMO_CONSENT_STATUS_DATA,
  DEMO_LOW_INVENTORY_DATA,
  DEMO_GUEST_RESIDENCY_DATA,
} from '@/lib/dashboard/demo-data'
import type { Database } from '@/lib/supabase/types'

type StudioRole = Database['public']['Tables']['studio_members']['Row']['role']

// ─── Greeting helper ──────────────────────────────────────────────────────────

function timeBasedGreeting(timezone: string): string {
  try {
    const hour = parseInt(
      new Intl.DateTimeFormat('en-US', {
        timeZone: timezone,
        hour: 'numeric',
        hour12: false,
      }).format(new Date()),
      10,
    )
    if (hour < 12) return 'Good morning'
    if (hour < 17) return 'Good afternoon'
    return 'Good evening'
  } catch {
    return 'Good morning'
  }
}

function formatDate(): string {
  return new Date().toLocaleDateString('en-US', {
    weekday: 'long',
    month: 'long',
    day: 'numeric',
  })
}

// ─── Props ────────────────────────────────────────────────────────────────────

interface TodayClientProps {
  firstName: string
  studioName: string
  timezone: string
  hasStudio: boolean
  studioId: string | null
  role: StudioRole
  ownArtistId?: string | null
  artistEarningsToday?: number
  gettingStartedCounts: GettingStartedCounts
  // New widget props from server loaders
  heroData: TodayHeroData | null
  urgentOverdueItem: UrgentOverdueItem | null
  nextUpItems: NextUpItem[]
  scheduleData: TodayScheduleData | null
  weekRevenueData: WeekRevenueData | null
  artistUtilizationData: ArtistUtilizationData | null
  pendingDepositsData: PendingDepositsData | null
  consentStatusData: ConsentStatusData | null
  lowInventoryData: LowInventoryData | null
  guestResidencyData: GuestResidencyData | null
}

// ─── Fallback data for when studioId is null ─────────────────────────────────

const EMPTY_HERO: TodayHeroData = {
  revenueToday: 0,
  revenueExpected: 0,
  revenueVsYesterday: 0,
  bookingsToday: 0,
  bookingsCompleted: 0,
  bookingsUpcoming: 0,
  depositsCollected: 0,
  depositsExpected: 0,
  depositsPendingCount: 0,
  nextUp: null,
  actionItemsTotal: 0,
  actionItemsOverdue: 0,
}

const EMPTY_PENDING_DEPOSITS: PendingDepositsData = { rows: [], totalCents: 0 }
const EMPTY_CONSENT_STATUS: ConsentStatusData = {
  signedCount: 0,
  totalCount: 0,
  unsignedRows: [],
}
const EMPTY_WEEK_REVENUE: WeekRevenueData = {
  days: [],
  totalCents: 0,
  prevTotalCents: 0,
  deltaPercent: null,
  todayIndex: 0,
}
const EMPTY_ARTIST_UTIL: ArtistUtilizationData = { rows: [], weekLabel: '' }

// ─── Component ────────────────────────────────────────────────────────────────

export function TodayClient({
  firstName,
  studioName,
  timezone,
  hasStudio,
  studioId,
  role,
  ownArtistId,
  artistEarningsToday = 0,
  gettingStartedCounts,
  heroData: heroProp,
  urgentOverdueItem: urgentOverdueProp,
  nextUpItems: nextUpProp,
  scheduleData: scheduleProp,
  weekRevenueData: weekRevenueProp,
  artistUtilizationData: artistUtilProp,
  pendingDepositsData: pendingDepositsProp,
  consentStatusData: consentStatusProp,
  lowInventoryData: lowInventoryProp,
  guestResidencyData: guestResidencyProp,
}: TodayClientProps) {
  const activityQuery = useRecentActivity(hasStudio)
  const alertsQuery = useDashboardAlerts(hasStudio)

  const [dismissedIds, setDismissedIds] = useState<string[]>([])
  const [checklistDismissed, setChecklistDismissed] = useState(false)

  // ── Demo mode ──────────────────────────────────────────────────────────────
  const [demoMode, setDemoMode] = useState(false)
  const [demoDismissed, setDemoDismissed] = useState(false)

  useEffect(() => {
    setChecklistDismissed(
      localStorage.getItem('inkos:getting-started:dismissed') === '1',
    )
    setDemoMode(localStorage.getItem('inkos:demo-mode') === '1')
  }, [])

  // ── Swap real → demo data when demo mode is on ─────────────────────────────
  const hero = demoMode ? DEMO_HERO_DATA : (heroProp ?? EMPTY_HERO)
  const urgentOverdueItem = demoMode ? null : urgentOverdueProp
  const nextUpItems = demoMode ? DEMO_NEXT_UP_ITEMS : nextUpProp
  const scheduleData = demoMode ? DEMO_SCHEDULE_DATA : scheduleProp
  const weekRevenueData = demoMode ? DEMO_WEEK_REVENUE_DATA : (weekRevenueProp ?? EMPTY_WEEK_REVENUE)
  const artistUtilizationData = demoMode
    ? DEMO_ARTIST_UTILIZATION_DATA
    : (artistUtilProp ?? EMPTY_ARTIST_UTIL)
  const pendingDepositsData = demoMode
    ? DEMO_PENDING_DEPOSITS_DATA
    : (pendingDepositsProp ?? EMPTY_PENDING_DEPOSITS)
  const consentStatusData = demoMode
    ? DEMO_CONSENT_STATUS_DATA
    : (consentStatusProp ?? EMPTY_CONSENT_STATUS)
  const lowInventoryData = demoMode ? DEMO_LOW_INVENTORY_DATA : lowInventoryProp
  const guestResidencyData = demoMode ? DEMO_GUEST_RESIDENCY_DATA : guestResidencyProp

  const visibleAlerts = (alertsQuery.data ?? []).filter(
    (a) => !dismissedIds.includes(a.id),
  )

  const showEmptyState = checklistDismissed && gettingStartedCounts.bookings === 0

  // KPI / hero row: owner/admin only — artists see earnings inside RoleAwareHero
  const showOwnerHero = role === 'owner' || role === 'admin'

  const greeting = timeBasedGreeting(timezone)
  const dateStr = formatDate()

  return (
    <div className="min-h-full bg-[var(--color-page-bg)]">
      <div className="mx-auto max-w-[1440px] space-y-6 px-4 pb-10 pt-6 sm:px-6 lg:px-8">

        {/* ── Shortcut overlay + command palette (handles all global hotkeys) ── */}
        <ShortcutOverlay />

        {/* ── Demo mode banner ── */}
        {demoMode && !demoDismissed && (
          <div className="flex items-center justify-between gap-4 rounded-xl border border-[var(--color-border)] bg-[var(--color-muted)] px-4 py-2.5">
            <p className="text-[12px] text-[var(--color-muted-foreground)]">
              Demo data — create a real booking to switch.
            </p>
            <button
              type="button"
              onClick={() => {
                localStorage.removeItem('inkos:demo-mode')
                setDemoMode(false)
                setDemoDismissed(true)
              }}
              className="shrink-0 text-[11px] font-medium text-[var(--color-foreground)] underline underline-offset-2 hover:no-underline focus-visible:outline-none"
            >
              Dismiss
            </button>
          </div>
        )}

        {/* ── Header ── */}
        <div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
          <div>
            <p className="mb-1 text-[11px] font-bold uppercase tracking-[0.08em] text-[var(--color-muted-foreground)]">
              {studioName}
            </p>
            <h1 className="font-display text-[52px] leading-[1.05] text-[var(--color-foreground)]">
              The studio,{' '}
              <span className="font-serif-italic text-[var(--color-rust)]">at a glance.</span>
            </h1>
            <p className="mt-2 text-sm text-[var(--color-muted-foreground)]">
              {dateStr} · {greeting}, {firstName}.{' '}
              {showOwnerHero && (
                <span className="font-medium text-[var(--color-foreground)]">
                  {hero.bookingsToday} session{hero.bookingsToday !== 1 ? 's' : ''} today
                  {hero.revenueExpected > 0 && (
                    <> · ${(hero.revenueExpected / 100).toLocaleString()} expected</>
                  )}
                  {hero.actionItemsOverdue > 0 && (
                    <> · <span className="text-[var(--color-rust)]">{hero.actionItemsOverdue} overdue</span></>
                  )}
                </span>
              )}
            </p>
          </div>
        </div>

        {/* ── Overdue alert banner (most urgent item, conditional) ── */}
        {urgentOverdueItem && <OverdueAlertBanner item={urgentOverdueItem} />}

        {/* ── Hero tile row — owner/admin only ── */}
        {showOwnerHero && <TodayHeroRow data={hero} />}

        {/* ── Today quick actions (card grid with descriptions) ── */}
        <TodayQuickActionsRow />

        {/* ── Legacy quick actions toolbar (shortcut buttons) ── */}
        <QuickActionsRow />

        {/* ── Getting started checklist ── */}
        <GettingStartedCard counts={gettingStartedCounts} />

        {showEmptyState ? (
          <EmptyDashboardState />
        ) : (
          <>
            {/* ── Role-aware hero: TodayQueue + role-specific widgets ── */}
            {hasStudio && studioId && (
              <RoleAwareHero
                role={role}
                studioId={studioId}
                ownArtistId={ownArtistId}
                artistEarningsToday={artistEarningsToday}
              />
            )}

            {/* ── Main widget grid ── */}
            {showOwnerHero && (
              <div className="grid grid-cols-1 gap-4 lg:grid-cols-3">
                {/* Left column: span 2 — Next Up + Schedule Timeline */}
                <div className="flex flex-col gap-4 lg:col-span-2">
                  <NextUpWidget items={nextUpItems} />
                  {scheduleData && (
                    <TodayScheduleTimelineWidget data={scheduleData} />
                  )}
                </div>

                {/* Right column: 6 widgets stacked */}
                <div className="flex flex-col gap-4">
                  <WeekRevenueTrajectoryWidget data={weekRevenueData} />
                  <ArtistUtilizationWidget data={artistUtilizationData} />
                  <PendingDepositsWidget data={pendingDepositsData} />
                  <ConsentStatusWidget data={consentStatusData} />
                  {/* Conditional: only renders when items below threshold */}
                  <LowInventoryWidget data={lowInventoryData} />
                  {/* Conditional: only renders when active residencies exist */}
                  <GuestResidencyWidget data={guestResidencyData} />
                </div>
              </div>
            )}

            {/* ── Activity + Alerts ── */}
            <div className="grid grid-cols-1 gap-4 lg:grid-cols-12">
              <div className="lg:col-span-12">
                <ActivityFeed
                  events={activityQuery.data ?? []}
                  loading={activityQuery.isLoading}
                  {...(studioId !== null ? { studioId } : {})}
                />
              </div>
            </div>

            {/* ── Alerts ── */}
            <AlertsCard
              alerts={visibleAlerts}
              loading={alertsQuery.isLoading}
              onDismiss={(id) =>
                setDismissedIds((prev) => [...prev, id])
              }
            />
          </>
        )}

      </div>
    </div>
  )
}

